package com.smartretail.supplier.entity;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="suppliers", uniqueConstraints=@UniqueConstraint(columnNames={"business_id","phone"})) public class Supplier { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="business_id",nullable=false) private Long businessId; @Column(nullable=false) private String name; @Column(nullable=false) private String phone; private String email; private String address; private String contactPerson; private String notes; @Column(name="created_at",nullable=false,updatable=false) private LocalDateTime createdAt; @PrePersist void created(){createdAt=LocalDateTime.now();} public Long getId(){return id;} public Long getBusinessId(){return businessId;} public void setBusinessId(Long v){businessId=v;} public String getName(){return name;} public void setName(String v){name=v;} public String getPhone(){return phone;} public void setPhone(String v){phone=v;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getAddress(){return address;} public void setAddress(String v){address=v;} public String getContactPerson(){return contactPerson;} public void setContactPerson(String v){contactPerson=v;} public String getNotes(){return notes;} public void setNotes(String v){notes=v;} public LocalDateTime getCreatedAt(){return createdAt;} }
